<template>
  <main class="version-page" aria-label="模型版本" data-version-page>
    <header class="page-head"><div><h1>模型版本</h1><p>快照、差异对比与回滚。</p></div><input v-model.trim="note" data-version-note placeholder="变更说明"><button type="button" data-version-create :disabled="busy || !modelId" @click="createVersion">新建版本</button></header>
    <p v-if="error" role="alert" class="error" data-error>{{ error }}</p><p v-if="busy" role="status" data-loading>正在加载…</p><p v-else-if="!modelId" class="empty" data-empty>请先在列表中选择一个模型。</p><p v-else-if="versions.length === 0" class="empty" data-version-empty>暂无版本快照</p>
    <table v-else data-version-list><thead><tr><th>版本</th><th>变更说明</th><th>创建人</th><th>创建时间</th><th>操作</th></tr></thead><tbody><tr v-for="row in versions" :key="row.id" :data-version-id="row.id"><td>v{{ row.version }}</td><td>{{ row.changeNote || '—' }}</td><td>{{ row.createdBy || '—' }}</td><td>{{ row.createdAt || '—' }}</td><td class="actions"><button type="button" :data-version-diff="row.id" @click="showDiff(row)">差异</button><button type="button" class="danger" :data-version-rollback="row.id" @click="rollback(row)">回滚</button></td></tr></tbody></table>
    <section v-if="diffOpen" ref="diffRef" class="dialog" data-version-diff-dialog :style="diffStyle"><header class="drag-handle" @pointerdown="onDiffPointerdown"><h2>版本差异 · v{{ activeVersion?.version }}</h2><button type="button" @click="diffOpen = false">关闭</button></header><div v-if="diff" class="diff-body"><h3>新增（{{ diff.added.length }}）</h3><p v-if="diff.added.length === 0" class="empty">无</p><ul v-else><li v-for="field in diff.added" :key="`a-${field.name}`" data-diff-added>{{ field.name }} · {{ field.dataType }}</li></ul><h3>删除（{{ diff.removed.length }}）</h3><p v-if="diff.removed.length === 0" class="empty">无</p><ul v-else><li v-for="field in diff.removed" :key="`r-${field.name}`" data-diff-removed>{{ field.name }} · {{ field.dataType }}</li></ul><h3>变更（{{ diff.changed.length }}）</h3><p v-if="diff.changed.length === 0" class="empty">无</p><ul v-else><li v-for="item in diff.changed" :key="`c-${item.name}`" data-diff-changed>{{ item.name }}：{{ item.before.dataType }} → {{ item.after.dataType }}</li></ul><p class="notes" data-diff-relations>关系变更：{{ diff.relationsChanged ? '是' : '否' }}</p></div></section>
  </main>
</template>
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import { useRoute } from 'vue-router'; import { modelApi, type ModelVersionRow, type ModelVersionDiff } from '../../services/rebuild/modelApi'; import { useDraggable } from '../../composables/useDraggable'
const props = defineProps<{ modelId?: number }>(); const route = useRoute(); const routeModelId = () => { const raw = route?.query?.modelId; const value = Number(Array.isArray(raw) ? raw[0] : raw); return Number.isFinite(value) && value > 0 ? value : undefined }; const modelId = computed(() => props.modelId ?? routeModelId())
/** D9：差异弹窗可由标题栏拖动；.dialog 用 translate 居中，拖拽定位后清除变换改由 left/top 落位 */
const diffRef = ref<HTMLElement | null>(null); const { dragStyle: diffDragStyle, onHandlePointerdown: onDiffPointerdown } = useDraggable(diffRef, diffRef, { storageKey: 'model.version-diff' }); const diffStyle = computed(() => (diffDragStyle.value.position ? { ...diffDragStyle.value, transform: 'none' } : diffDragStyle.value))
const versions = ref<ModelVersionRow[]>([]); const note = ref(''); const busy = ref(false); const error = ref(''); const diffOpen = ref(false); const activeVersion = ref<ModelVersionRow | null>(null); const diff = ref<ModelVersionDiff | null>(null); const message = (cause: unknown) => cause instanceof Error ? cause.message : String(cause)
async function load() { const id = modelId.value; if (!id) { versions.value = []; return } busy.value = true; error.value = ''; try { versions.value = await modelApi.listVersions(id) } catch (cause) { error.value = message(cause); versions.value = [] } finally { busy.value = false } }
async function createVersion() { const id = modelId.value; if (!id) return; busy.value = true; error.value = ''; try { await modelApi.createVersion(id, { changeNote: note.value }); note.value = ''; await load() } catch (cause) { error.value = message(cause) } finally { busy.value = false } }
async function showDiff(row: ModelVersionRow) { const id = modelId.value; if (!id) return; busy.value = true; error.value = ''; try { activeVersion.value = row; diff.value = await modelApi.diffVersion(id, row.id); diffOpen.value = true } catch (cause) { error.value = message(cause) } finally { busy.value = false } }
async function rollback(row: ModelVersionRow) { const id = modelId.value; if (!id) return; busy.value = true; error.value = ''; try { await modelApi.rollbackVersion(id, row.id); await load() } catch (cause) { error.value = message(cause) } finally { busy.value = false } }
onMounted(load)
</script>
<style scoped>
.version-page{max-width:1440px;margin:auto;padding:32px 24px;color:var(--text)}.page-head{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.page-head>div{margin-right:auto}.page-head h1{margin:0}.page-head p{margin:6px 0 0;color:var(--text-2)}input,button{padding:7px 10px}.error{color:var(--danger)}.empty{color:var(--text-3)}table{width:100%;border-collapse:collapse;background:var(--card);margin-top:18px}th,td{text-align:left;padding:10px;border-bottom:1px solid var(--border)}.actions{display:flex;gap:6px;flex-wrap:wrap}.danger{color:var(--danger)}.dialog{position:fixed;z-index:20;left:50%;top:50%;transform:translate(-50%,-50%);width:min(760px,calc(100vw - 48px));max-height:80vh;overflow:auto;background:var(--card);border:1px solid var(--border-strong);border-radius:var(--radius-lg);box-shadow:var(--shadow-lg);padding:20px}.dialog header{display:flex;align-items:center;justify-content:space-between}.dialog h2,.dialog h3{margin:0}.diff-body h3{margin-top:14px;color:var(--text-2)}.notes{color:var(--text-2)}.drag-handle{cursor:grab;user-select:none}.drag-handle:active{cursor:grabbing}
</style>
